"""Write a Workflow script that runs every prepared extraction job (args.json embedded as data).

    python make_workflow.py <jobs_dir> <out.js> <name>
"""
import json
import sys
from pathlib import Path

jobs_dir, out, name = Path(sys.argv[1]), Path(sys.argv[2]), sys.argv[3]
data = json.loads((jobs_dir / "args.json").read_text())

TEMPLATE = r"""export const meta = {
  name: '__NAME__',
  description: 'Read every mailbox document into typed facts for the harness cache (baseline, no API key)',
  phases: [{ title: 'Emails', detail: 'one reader per email: its facts and its attachments\' kinds' },
           { title: 'Attachments', detail: 'one reader per attachment, with the schema for its kind' }],
}
const DATA = __DATA__
const EFFORT = { contract: 'medium', contract_instrument: 'medium', tracking_export: 'medium', ap_register: 'medium' }
const wrap = (schema) => ({ type: 'object', additionalProperties: false, required: ['job_id', 'facts'],
  properties: { job_id: { type: 'string' }, facts: schema } })
const ask = (task, id) => `${DATA.system}

${task}

Set job_id to "${id}". Put the facts in "facts". Every src field uses the [page:line] tags exactly as shown in the
document ("2:14", or "2:14-16" for consecutive lines). Read the whole document before answering.`

const results = await pipeline(DATA.emails,
  (e) => agent(ask(`Read the file ${e.path} with the Read tool: it holds your task and the email, every line tagged ` +
                   `[page:line]. Return the facts it asks for.`, 'email:' + e.id),
               { label: 'email ' + e.id.slice(0, 8), phase: 'Emails', schema: wrap(DATA.schemas.email), effort: 'low' }),
  (ef, e) => parallel(e.atts.map((a) => async () => {
    const kinds = Object.fromEntries(((ef && ef.facts && ef.facts.attachment_kinds) || []).map((k) => [k.name, k.kind]))
    const kind = kinds[a.name] || 'other'
    let where = `Read the file ${a.path} with the Read tool: it holds the document, every line tagged [page:line].`
    if (a.pngs) {
      const pages = []
      for (const png of a.pngs) {
        const t = await agent(`Read the image ${png} with the Read tool. ${DATA.transcribe}
Set job_id to "scan:${a.id}".`, { label: 'scan ' + a.id.slice(0, 8), phase: 'Attachments', effort: 'medium',
          schema: wrap({ type: 'object', additionalProperties: false, required: ['lines'],
                         properties: { lines: { type: 'array', items: { type: 'string' } } } }) })
        pages.push(t ? t.facts.lines : [])
      }
      const text = pages.map((ls, p) => `=== page ${p + 1} ===\n` + ls.map((l, i) => `[${p + 1}:${i + 1}] ${l}`).join('\n')).join('\n')
      where = `The document (a scanned page we transcribed), every line tagged [page:line]:\n<document>\n${text}\n</document>`
    }
    const r = await agent(ask(`${DATA.instr[kind]}\n\n${where}`, kind + ':' + a.id),
                          { label: kind + ' ' + a.name, phase: 'Attachments', schema: wrap(DATA.schemas[kind]),
                            effort: EFFORT[kind] || 'low' })
    return { id: a.id, kind, ok: !!r }
  })).then((rs) => ({ email: e.id, ok: !!ef, atts: rs })))
const flat = results.filter(Boolean)
const failed = flat.flatMap((r) => [...(r.ok ? [] : ['email:' + r.email]), ...r.atts.filter((a) => !a || !a.ok).map((a) => a ? a.kind + ':' + a.id : '?')])
log(`${flat.length} emails done; ${failed.length} failed`)
return { emails: flat.length, failed }
"""
out.write_text(TEMPLATE.replace("__NAME__", name).replace("__DATA__", json.dumps(data)))
print(f"wrote {out} ({out.stat().st_size // 1024} KB)")

