def _found(x, acc):
    """Every {"job_id", "facts"} object anywhere in a journal entry."""
    if isinstance(x, dict):
        if isinstance(x.get("job_id"), str) and isinstance(x.get("facts"), dict):
            acc.append(x)
        for v in x.values():
            _found(v, acc)
    elif isinstance(x, list):
        for v in x:
            _found(v, acc)
    elif isinstance(x, str) and '"job_id"' in x:
        try:
            _found(json.loads(x), acc)
        except ValueError:
            pass
    return acc


def harvest(out: Path, journal: Path) -> None:
    """Write each agent's facts into the harness cache under the key llm.extract() / llm.transcribe() look up."""
    import hashlib
    cdir = llm.cache_dir(out)
    got, scans = {}, {}
    for line in journal.read_text().splitlines():
        try:
            entry = json.loads(line)
        except ValueError:
            continue
        for r in _found(entry, []):
            kind, _, sha = r["job_id"].partition(":")
            if kind == "scan":
                scans.setdefault(sha, "\n".join(r["facts"].get("lines") or []))
            elif kind in llm.SCHEMAS:
                got[(kind, sha)] = r["facts"]
    for sha, text in scans.items():
        got[("scan", sha)] = {"pages": [text]}
    for (kind, sha), val in got.items():
        key = f"{llm.PROMPT_VERSION}|{llm.MODEL}|{kind}|{sha}"
        (cdir / f"{hashlib.sha256(key.encode()).hexdigest()[:32]}.json").write_text(json.dumps(val))
    kinds = {}
    for k, _ in got:
        kinds[k] = kinds.get(k, 0) + 1
    print(f"cached {len(got)} results in {cdir}: {kinds}")

