const verifyPrompt = (a, fs) => `Adversarially check these reported bugs in the ${a.key} area of ${REPO}/harness/engine.py against ${REPO}/GLOSSARY.md, which is the specification. For each one, read the code path and the glossary yourself and try to refute it. Is the triggering input really glossary-valid and plausible? Does the code really do what is claimed (check callers and earlier guards)? Would the glossary really require something else? Answer real=false when the claim is unsupported, already handled elsewhere, or when the expected behaviour is a guess the glossary does not settle. If it is real but the proposed fix is wrong or broader than needed, give a corrected smallest fix. Don't run make targets.

Findings:
${JSON.stringify(fs, null, 1)}`

const results = await pipeline(AREAS,
  (a) => agent(findPrompt(a), { label: 'find ' + a.key, phase: 'Find', schema: FINDINGS, effort: 'high' }),
  async (r, a) => {
    const fs = (r && r.findings) || []
    if (!fs.length) return { area: a.key, confirmed: [], refuted: 0 }
    const v = await agent(verifyPrompt(a, fs), { label: 'verify ' + a.key, phase: 'Verify', schema: VERDICTS, effort: 'high' })
    const byId = Object.fromEntries(((v && v.verdicts) || []).map((x) => [x.id, x]))
    const confirmed = fs.filter((f) => byId[f.id] && byId[f.id].real)
      .map((f) => ({ area: a.key, ...f, verifier: byId[f.id].why, corrected_fix: byId[f.id].corrected_fix || null }))
    log(`${a.key}: ${fs.length} reported, ${confirmed.length} confirmed`)
    return { area: a.key, confirmed, refuted: fs.length - confirmed.length, unverified: v ? 0 : fs.length }
  })
const done = results.filter(Boolean)
return { confirmed: done.flatMap((x) => x.confirmed), refuted: done.reduce((n, x) => n + x.refuted, 0),
         areas_failed: AREAS.length - done.length }

