  phases: [
    { title: 'Find', detail: 'one auditor per file group' },
    { title: 'Verify', detail: 'one skeptic per group checks every proposed cut' },
  ],
}

const REPO = '/Users/soumyayotimohanta/Developer/nova-takehome'
const GROUPS = [
  { key: 'engine', files: 'harness/engine.py' },
  { key: 'reader-llm-cli', files: 'harness/llm.py, harness/docs.py, harness/harness.py' },
  { key: 'evals-tests', files: 'evals/build_cases.py, harness/test_engine.py, harness/test_parse.py, .gitignore' },
]
const CUTS = { type: 'object', required: ['cuts'], properties: { cuts: { type: 'array', items: {
  type: 'object', required: ['id', 'tag', 'what', 'replacement', 'where', 'lines_saved'],
  properties: {
    id: { type: 'string' }, tag: { type: 'string', enum: ['delete', 'stdlib', 'native', 'yagni', 'shrink'] },
    what: { type: 'string', description: 'what to cut, specific' },
    replacement: { type: 'string', description: 'what replaces it: nothing, the stdlib function, or the shorter form' },
    where: { type: 'string', description: 'file:line(s)' }, lines_saved: { type: 'integer' } } } } } }
const CHECKS = { type: 'object', required: ['checks'], properties: { checks: { type: 'array', items: {
  type: 'object', required: ['id', 'keep', 'why', 'lines_saved'],
  properties: { id: { type: 'string' }, keep: { type: 'boolean', description: 'true = the cut is wrong or risky, keep the code' },
                why: { type: 'string' }, lines_saved: { type: 'integer' } } } } } }

const findPrompt = (g) => `Over-engineering audit (ponytail-audit) of part of a Python harness in ${REPO}. Scope: ${g.files}. Out of scope: grader/, tools/, evals/run_evals.py, Makefile and data/ (they ship with the task and must stay as they are), and correctness bugs, security and performance (a separate review covers those).

Context: harness/harness.py is the CLI the grader calls (ingest, report, feedback). harness/llm.py asks Claude to extract each document into JSON matching the schemas defined there; every schema field costs output tokens on every document, so a field the engine never reads is a real recurring cost. harness/engine.py applies GLOSSARY.md's rules in plain Python. harness/docs.py reads mailboxes and copies grader/extract.py's text functions; the README says grader/extract.py may be used as your own reader. evals/build_cases.py generates eval mailboxes (dev tooling the grader never runs). harness/test_engine.py and test_parse.py are the runnable checks.

Hunt for: dead code (functions, parameters, dict keys or fields set but never read), schema fields in llm.py the engine never reads (grep engine.py and harness.py for the exact key before claiming), hand-rolled stdlib, wrappers that only delegate, layers with one caller, flags or config nobody sets, duplicated logic, and the same logic in fewer lines. Grep callers before calling anything unused. Keep error handling that prevents a failed run or lost data, and keep anything GLOSSARY.md requires.

Tags: delete (the replacement is nothing), stdlib (name the function), native, yagni, shrink (show the shorter form). For each cut give the tag, what to cut, the replacement, file:line(s) and the estimated lines saved. Rank the biggest cut first; up to 15 cuts. An empty list is a valid answer.`

const verifyPrompt = (g, cuts) => `Check these proposed simplifications to ${g.files} in ${REPO}. For each, verify it yourself with grep and by reading the code. Is it really unused or redundant (check every caller, dict keys read elsewhere, fields read by the tests or by evals/run_evals.py and grader/)? Would the replacement behave the same on edge cases? Would removing an llm.py schema field drop a key that engine.py or harness.py reads (search for the exact key), or one GLOSSARY.md needs? Set keep=true when the cut is wrong, risky, or removes error handling that prevents a failed run. Give your own estimate of lines saved. Don't run make targets.

Cuts:
${JSON.stringify(cuts, null, 1)}`

const results = await pipeline(GROUPS,
  (g) => agent(findPrompt(g), { label: 'find ' + g.key, phase: 'Find', schema: CUTS, effort: 'high' }),
  async (r, g) => {
    const cuts = (r && r.cuts) || []
    if (!cuts.length) return { group: g.key, kept: [], cuts: [] }
    const v = await agent(verifyPrompt(g, cuts), { label: 'verify ' + g.key, phase: 'Verify', schema: CHECKS, effort: 'high' })
    const by = Object.fromEntries(((v && v.checks) || []).map((x) => [x.id, x]))
    const ok = cuts.filter((c) => by[c.id] && !by[c.id].keep)
      .map((c) => ({ group: g.key, ...c, lines_saved: by[c.id].lines_saved, check: by[c.id].why }))
    const kept = cuts.filter((c) => !by[c.id] || by[c.id].keep)
      .map((c) => ({ id: c.id, what: c.what, why: by[c.id] ? by[c.id].why : 'not verified' }))
    log(`${g.key}: ${cuts.length} proposed, ${ok.length} survive`)
    return { group: g.key, cuts: ok, kept }
  })
const done = results.filter(Boolean)
return { cuts: done.flatMap((x) => x.cuts).sort((a, b) => b.lines_saved - a.lines_saved),
         rejected: done.flatMap((x) => x.kept), groups_failed: GROUPS.length - done.length }

